class Solution {
  public int maxDistance(String s, int k) {
    int x = 0, y = 0, best = 0;
    for (int i = 0; i < s.length(); i++) {
      switch (s.charAt(i)) {
        case 'N':
          y++;
          break;
        case 'S':
          y--;
          break;
        case 'E':
          x++;
          break;
        default:
          x--;
          break;
      }
      // each change can add 2 to the distance, but it can never exceed the steps taken
      best = Math.max(best, Math.min(Math.abs(x) + Math.abs(y) + 2 * k, i + 1));
    }
    return best;
  }
}
